'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(path,options={})=>{const r=await fetch('/api'+path,options);const j=await r.json();if(!r.ok)throw new Error(typeof j.detail==='string'?j.detail:'Request failed');return j};
let allPlaces=[];
async function loadPlaces(){try{allPlaces=await api('/destinations');renderPlaces('all')}catch(e){$('#destinationGrid').textContent='Destinations unavailable: '+e.message}}
function renderPlaces(filter){let list=allPlaces.filter(p=>filter==='all'||p.category===filter);$('#destinationGrid').innerHTML=list.map(p=>`<article class="place-card"><div class="place-pattern"></div><div class="place-content"><small>${escapeHTML(p.eyebrow)} · ${escapeHTML(p.area)}</small><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.description)}</p><button data-place="${escapeHTML(p.slug)}">Discover the story ↗</button></div></article>`).join('')||'<p>No places in this category yet.</p>';$$('[data-place]').forEach(b=>b.onclick=()=>{const p=allPlaces.find(x=>x.slug===b.dataset.place);if(p)alert(p.name+'\n\n'+p.highlights+'\n\nHeritage & access note: '+p.advisory)})}
$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(n=>n.classList.toggle('active',n===b));renderPlaces(b.dataset.filter)});
$$('[data-v]').forEach(b=>b.onclick=()=>b.classList.toggle('selected'));
$('#planner').addEventListener('submit',async e=>{e.preventDefault();const b=$('#planBtn');b.disabled=true;b.textContent='Curating your experience…';try{const p=await api('/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({interests:$$('[data-v].selected').map(x=>x.dataset.v),days:Number($('#days').value),pace:$('#pace').value,question:$('#question').value})});$('#planResult').innerHTML=`<h3>${escapeHTML(p.title)}</h3>${p.guide?`<p>${escapeHTML(p.guide)}</p>`:''}${p.days.map(d=>`<div class="result-day"><strong>DAY ${d.day}</strong>${d.stops.length?d.stops.map(s=>`<h4>${escapeHTML(s.name)}</h4><p>${escapeHTML(s.reason)}</p>`).join(''):'<p>Time to reflect and explore virtually.</p>'}</div>`).join('')}<p class="disclaimer">${escapeHTML(p.notice)}</p><small>${escapeHTML(p.mode)} · ${escapeHTML(p.recommendations_source)}</small>`}catch(err){$('#planResult').textContent=err.message}finally{b.disabled=false;b.innerHTML='Create my discovery <span>✦</span>'}});
async function loadMemories(){try{const stories=await api('/memories');if(stories.length)$('#memoryCards').innerHTML=stories.map(s=>`<article class="story-card"><small>${escapeHTML(s.destination)} · ${escapeHTML(s.display_name)}</small><h3>${escapeHTML(s.title)}</h3><p>${escapeHTML(s.story).slice(0,430)}</p></article>`).join('')}catch(e){console.warn('Story gallery unavailable',e)}}
$('#memoryForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const p={display_name:$('#display_name').value,title:$('#story_title').value,story:$('#story').value,destination:$('#destination').value,image_url:$('#image_url').value||null,consent:$('#consent').checked};const r=await api('/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});$('#storyStatus').textContent=r.message;e.target.reset()}catch(err){$('#storyStatus').textContent='Could not submit: '+err.message}finally{b.disabled=false}});
const ah=()=>({'X-Admin-Token':$('#adminToken').value});
async function loadAdmin(){try{const [overview,stories]=await Promise.all([api('/admin/overview',{headers:ah()}),api('/admin/memories',{headers:ah()})]);$('#adminData').innerHTML=`<h3>Editorial overview</h3><p>${overview.destinations} destinations · ${overview.memories} memories · ${overview.pending_memories} awaiting review</p><h3>Review queue</h3>`+(stories.map(s=>`<div class="admin-row"><strong>${escapeHTML(s.title)}</strong> — ${escapeHTML(s.display_name)} · ${escapeHTML(s.status)}<p>${escapeHTML(s.story)}</p><button data-review="${escapeHTML(s.id)}" data-status="approved">Approve</button><button data-review="${escapeHTML(s.id)}" data-status="rejected">Reject</button></div>`).join('')||'<p>No submissions to review.</p>');$$('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review,b.dataset.status))}catch(err){$('#adminData').textContent=err.message}}
async function review(id,status){try{await api('/admin/memories/'+encodeURIComponent(id),{method:'PATCH',headers:{...ah(),'Content-Type':'application/json'},body:JSON.stringify({status,featured:false})});await loadAdmin();await loadMemories()}catch(err){alert(err.message)}}
$('#adminLoad').onclick=loadAdmin;
loadPlaces();loadMemories();
